const exec = $json.execution;
const lastNode = exec?.lastNodeExecuted || 'نامشخص';
const errorMsg = exec?.error?.message || 'نامشخص';
const execId = exec?.id || 'نامشخص';
const execUrl = exec?.url || '';

return {
  json: {
    subject: '[Hamoon] یک اجرای Workflow با خطای غیرمنتظره متوقف شد',
    text: `این یک هشدار پشتیبان است — خرابی‌های شناخته‌شده (خطای AI، خطای Google Sheets، صفحه منبع نامشخص) قبلاً داخل خودِ Workflow اصلی مدیریت و ثبت می‌شوند و اینجا اطلاعشان به شما نمی‌رسد.\n\nاین ایمیل یعنی یک خطای پیش‌بینی‌نشده باعث توقف کامل یک اجرا شده — مثلاً یک Node بد پیکربندی شده یا یک Bug. اطلاعات کامل Submission در این ایمیل موجود نیست (محدودیت فنی n8n: Error Trigger به داده ورودی اجرای شکست‌خورده دسترسی ندارد).\n\nلطفاً همین حالا وارد n8n شوید و اجرای شکست‌خورده را بررسی کنید تا اگر Submissionای واقعاً از دست رفته، آن را پیدا و دستی ثبت کنید:\nNode خطا: ${lastNode}\nپیام خطا: ${errorMsg}\nExecution ID: ${execId}\n${execUrl ? 'لینک: ' + execUrl : ''}\nزمان: ${new Date().toISOString()}`,
  },
};
